    },
    {
      name: 'Christ the Redeemer',
      location: 'Brazil',
      description: 'An Art Deco statue of Jesus Christ in Rio de Janeiro.',
      image: 'https://images.unsplash.com/photo-1483729558449-99ef09a8c325?w=500',
    },
    {
      name: 'Machu Picchu',
      location: 'Peru',
      description: 'A 15th-century Inca citadel set high in the Andes Mountains.',
      image: 'https://images.unsplash.com/photo-1587595431973-160d0d94add1?w=500',
    },
    {
      name: 'Chichen Itza',
      location: 'Mexico',
      description: 'A large pre-Columbian archaeological site built by the Maya civilization.',
